record.field:
# The builder exports hrefs containing database ids (/shop/day-pass-3,
# /appointment/2). Those ids differ on every install, so the pages ship with
# *tokens* instead and we swap in the real website_url here.
tokens = {
    '*day_pass_product*': 'coworking.product_template_3',
    '*flex_product*': 'coworking.product_template_5',
    '*resident_product*': 'coworking.product_template_6',
    '*desk_appointment*': 'coworking.appointment_type_1',   # Shared desk
    '*tour_appointment*': 'coworking.appointment_type_2',   # Free tour
    '*room_appointment*': 'coworking.appointment_type_3',   # Meeting Room
}
urls = {}
for token, xml_id in tokens.items():
    record = env.ref(xml_id, raise_if_not_found=False)
    if record and record.website_url:
        urls[token] = record.website_url

views = [
    'coworking.view_page_home',
    'coworking.view_page_membership',
    'coworking.header_call_to_action',
]
for xml_id in views:
    view = env.ref(xml_id, raise_if_not_found=False)
    if not view:
        continue
    arch = view.arch
    for token, url in urls.items():
        arch = arch.replace(token, url)
    if arch != view.arch:
        view.write({'arch': arch})
